<script>
 import { tick } from 'svelte';
 import './disk-native.css';
 let { state: nativeDiskUtilityState, windowId, profile, controller, execute, registerView } = $props();
 let root = $state(), scroller = $state(), feedback = $state('');
 let name = $state(''), format = $state('APFS'), capacityBytes = $state(0), sourceRootId = $state(''), collision = $state('replace'), imageFileId = $state(''), imageFormat = $state('iso');
 const bytes = n => new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format((n ?? 0) / 1e9) + ' GB';
 let session = $derived(nativeDiskUtilityState.sessions.find(row => row.windowId === windowId));
 let windows = $derived(profile.id.startsWith('windows'));
 let classic = $derived(/high-sierra|mojave/.test(profile.id));
 let volumes = $derived.by(() => { void nativeDiskUtilityState; void session; return controller.getVolumes(); });
 let files = $derived.by(() => { void nativeDiskUtilityState; void session; return controller.getFiles(); });
 let selected = $derived(volumes.find(row => row.id === session?.selectedId));
 let imageFiles = $derived(files.filter(row => row.kind !== 'folder' && /\.(iso|vhd)$/i.test(row.name)));
 let running = $derived(session?.stage === 'running');
 async function send(command, payload = {}) { try { const result = await execute(command, { windowId }, payload); feedback = result?.status === 'rejected' ? result.error?.message ?? 'The operation could not be completed.' : ''; return result; } catch (error) { feedback = error.message; } }
 $effect(() => { const panel = session?.panel, volume = selected; if (panel && volume) { name = panel === 'partition' ? 'Untitled' : volume.name; format = ['APFS','HFS+','FAT32','NTFS'].includes(volume.format) ? volume.format : windows ? 'NTFS' : 'APFS'; capacityBytes = Math.floor(volume.capacityBytes / 2); sourceRootId = ''; } if (panel === 'image' || panel === 'convert') { imageFileId = ''; name = 'Disk Image'; } });
 $effect(() => {
  const original = root, originalScroller = scroller, originalSession = session;
  if (!original || !originalScroller || !originalSession) return;
  let retired = false;
  const available = () => !retired && root === original && scroller === originalScroller && original.isConnected && nativeDiskUtilityState.sessions.find(row => row.windowId === windowId) === originalSession;
  const find = (attribute, id) => [...original.querySelectorAll(`[${attribute}]`)].find(node => node.getAttribute(attribute) === id && node.getClientRects().length && !node.disabled && !node.closest('[inert]'));
  const reject = () => ({ status: 'rejected', error: { code: 'stale_target', message: 'The original mounted Disk Utility view is unavailable.' } });
  const view = { available, describe: () => available() ? { windowId, controlIds: [...original.querySelectorAll('[data-disk-control]')].map(node => node.dataset.diskControl), areaIds: ['volumes','content'] } : null,
   async focus(target, guard = () => true) { const controlId = typeof target === 'string' ? target : target.controlId; const node = find('data-disk-control', controlId); if (!available() || guard() !== true || !node) return reject(); node.focus(); await tick(); return available() && guard() === true && find('data-disk-control', controlId) === node && node.ownerDocument.activeElement === node ? { status: 'applied', controlId } : reject(); },
   async scroll({ areaId = 'content', top = 0, left = 0 }, guard = () => true) { const node = find('data-disk-area', areaId); if (!available() || guard() !== true || !node) return reject(); node.scrollTo({ top, left, behavior: 'instant' }); await tick(); return available() && guard() === true && find('data-disk-area', areaId) === node ? { status: 'applied', areaId, top: node.scrollTop, left: node.scrollLeft } : reject(); }, destroy() { retired = true; } };
  const unregister = registerView(windowId, view); return () => { view.destroy(); if (typeof unregister === 'function') unregister(); };
 });
 function sheetKeys(event) { if (event.key === 'Escape' && !running) { event.preventDefault(); void send('disk.cancel'); } if (event.key === 'Tab') { const controls = [...event.currentTarget.querySelectorAll('button,input,select')].filter(node => !node.disabled); const first = controls[0], last = controls.at(-1); if (event.shiftKey && event.target === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && event.target === last) { event.preventDefault(); first?.focus(); } } }
 $effect(() => { if (session?.panel && session.panel !== 'none') void tick().then(() => root?.querySelector('[role="dialog"] button, [role="dialog"] input, [role="dialog"] select')?.focus()); });
</script>

{#if session}
<section bind:this={root} class="disk-native disk-utility" class:disk-classic={classic} class:disk-windows={windows} aria-label={windows ? 'Disk Utility local equivalent' : 'Disk Utility'}>
 <header class="disk-toolbar" aria-label="Disk Utility toolbar" inert={session.panel && session.panel !== 'none'}>
  <label class="disk-view-picker">View<select data-disk-control="view" value={session.viewMode ?? 'volumes'} disabled={running} onchange={event => send('disk.view', { mode: event.currentTarget.value })}><option value="volumes">Show Only Volumes</option><option value="all">Show All Devices</option></select></label>
  <div class="disk-toolbar-actions">{#each [['firstAid','✚','First Aid'],['partition','◴','Partition'],['erase','▰','Erase'],['restore','↶','Restore']] as [panel, icon, label]}<button data-disk-control={panel} disabled={!selected || running} onclick={() => send('disk.panel', { panel })}><span aria-hidden="true">{icon}</span>{label}</button>{/each}<button data-disk-control="mount" disabled={!selected || running} onclick={() => send('disk.mount', { mounted: !selected.mounted })}><span aria-hidden="true">⏏</span>{selected?.mounted ? 'Unmount' : 'Mount'}</button><button data-disk-control="info" disabled={!selected || running} onclick={() => send('disk.info')}><span aria-hidden="true">ⓘ</span>Info</button></div>
 </header>
 {#if windows}<p class="disk-disclosure">Functional local Disk Utility equivalent, not Windows Disk Management. Changes affect only this scene’s Files and volumes.</p>{:else if profile.id.includes('golden-gate')}<p class="disk-disclosure">Native macOS 27 appearance is unverified; nearest macOS 26-inspired layout. Local scene volumes only.</p>{/if}
 <div class="disk-split" inert={session.panel && session.panel !== 'none'}>
  <aside class="disk-sidebar" data-disk-area="volumes" tabindex="0" aria-label="Storage devices and volumes">
   {#each [true, false] as internal}<h2>{internal ? 'Internal' : 'External'}</h2>{#if session.viewMode === 'all'}{#each nativeDiskUtilityState.devices.filter(device => device.internal === internal) as device}<div class="disk-device"><span class="disk-small-drive" aria-hidden="true"></span><span>{device.model}<small>{bytes(device.capacityBytes)}</small></span></div>{#each volumes.filter(volume => volume.deviceId === device.id) as volume}<button class="disk-volume nested" class:chosen={selected?.id === volume.id} data-disk-control={`volume:${volume.id}`} aria-pressed={selected?.id === volume.id} disabled={running} onclick={() => send('disk.select', { volumeId: volume.id })}><span class="disk-small-drive" aria-hidden="true"></span><span>{volume.name}<small>{volume.mounted ? volume.format : 'Not mounted'}</small></span></button>{/each}{/each}{:else}{#each volumes.filter(volume => volume.internal === internal) as volume}<button class="disk-volume" class:chosen={selected?.id === volume.id} data-disk-control={`volume:${volume.id}`} aria-pressed={selected?.id === volume.id} disabled={running} onclick={() => send('disk.select', { volumeId: volume.id })}><span class="disk-small-drive" aria-hidden="true"></span><span>{volume.name}<small>{volume.mounted ? volume.format : 'Not mounted'}</small></span></button>{/each}{/if}{/each}
   <h2>Disk Images</h2><button class="disk-sidebar-action" data-disk-control="image" disabled={running} onclick={() => send('disk.panel', { panel: 'image' })}>Open or Create Image…</button><button class="disk-sidebar-action" data-disk-control="convert" disabled={running} onclick={() => send('disk.panel', { panel: 'convert' })}>Convert Image…</button>
  </aside>
  <main bind:this={scroller} class="disk-detail" data-disk-area="content" tabindex="0">
   {#if selected}<div class="disk-volume-heading"><span class="disk-large-drive" aria-hidden="true"></span><div><h1>{selected.name}</h1><p>{selected.internal ? 'Internal' : 'External'} · {selected.format} · {selected.mounted ? 'Mounted' : 'Not mounted'}</p></div><strong>{bytes(selected.capacityBytes)}</strong></div><div class="disk-storage-bar" aria-label={`${bytes(selected.usedBytes)} used, ${bytes(Math.max(0, selected.capacityBytes - selected.usedBytes))} available`}><span style:width={`${selected.capacityBytes ? Math.min(100, selected.usedBytes / selected.capacityBytes * 100) : 0}%`}></span></div><div class="disk-storage-legend"><span><i></i>Used: {bytes(selected.usedBytes)}</span><span>Free: {bytes(Math.max(0, selected.capacityBytes - selected.usedBytes))}</span></div><dl class="disk-properties"><dt>Volume name</dt><dd>{selected.name}</dd><dt>Format</dt><dd>{selected.format}</dd><dt>Capacity</dt><dd>{bytes(selected.capacityBytes)}</dd><dt>Available</dt><dd>{bytes(Math.max(0, selected.capacityBytes - selected.usedBytes))}</dd><dt>Device</dt><dd>{nativeDiskUtilityState.devices.find(device => device.id === selected.deviceId)?.model ?? selected.deviceId}</dd><dt>Mount point</dt><dd>{selected.mounted ? selected.rootFileId : 'Not mounted'}</dd>{#if selected.driveLetter}<dt>Drive letter</dt><dd>{selected.driveLetter}</dd>{/if}</dl><p class="disk-local-note">Operations use the actual local Files tree. No host disk is read, partitioned, or erased.</p>{:else}<div class="disk-empty"><span class="disk-large-drive" aria-hidden="true"></span><h1>Select a volume</h1><p>Choose a volume in the sidebar to view its capacity and perform disk operations.</p></div>{/if}
  </main>
 </div>
 {#if session.panel && session.panel !== 'none'}
 <div class="disk-sheet-shade"><section class="disk-sheet" role="dialog" aria-modal="true" aria-label={`${session.panel} disk operation`} tabindex="-1" onkeydown={sheetKeys}>
  {#if session.panel === 'info'}<h2>Information: {selected?.name ?? 'Volume unavailable'}</h2>{#if selected}<dl class="disk-properties"><dt>Volume identifier</dt><dd>{selected.id}</dd><dt>Files root</dt><dd>{selected.rootFileId}</dd><dt>Device identifier</dt><dd>{selected.deviceId}</dd><dt>Format</dt><dd>{selected.format}</dd><dt>Capacity in bytes</dt><dd>{selected.capacityBytes.toLocaleString('en-US')}</dd><dt>Used bytes</dt><dd>{selected.usedBytes.toLocaleString('en-US')}</dd><dt>Mounted</dt><dd>{selected.mounted ? 'Yes' : 'No'}</dd></dl>{/if}<div class="disk-actions"><button onclick={() => send('disk.cancel')}>Done</button></div>
  {:else if session.panel === 'firstAid'}<h2>Run First Aid on “{selected?.name}”?</h2><p>First Aid checks the local volume’s structure and reports any inconsistencies in its actual Files tree.</p>{#if running}<progress max="100" value={session.progress} aria-label="First Aid progress"></progress>{/if}<p role="status">{session.message}</p><div class="disk-actions"><button onclick={() => send('disk.cancel')}>{running ? 'Cancel' : 'Done'}</button><button class="disk-default" disabled={!selected || running} onclick={() => send('disk.firstAid')}>Run</button></div>
  {:else if session.panel === 'erase' || session.panel === 'partition'}<h2>{session.panel === 'erase' ? 'Erase' : 'Partition'} “{selected?.name}”?</h2><p>{session.panel === 'erase' ? 'Erase permanently removes every writable user file and all Trash bytes in this virtual volume. Immutable OS/profile folders are retained. This action cannot be undone.' : 'Create a new local volume with the capacity below. Existing files must still fit in the remaining space.'}</p><label>Name<input data-disk-control="name" bind:value={name} disabled={running}/></label><label>Virtual file-system model<select data-disk-control="format" bind:value={format} disabled={running}><option value="APFS">APFS</option><option value="HFS+">Mac OS Extended (Journaled)</option><option value="FAT32">MS-DOS (FAT)</option>{#if windows}<option value="NTFS">NTFS</option>{/if}</select></label><p class="disk-local-note">These formats describe the virtual Files volume model, not a raw host filesystem formatter.</p>{#if session.panel === 'partition'}<label>New volume capacity (bytes)<input data-disk-control="capacity" type="number" min="65536" max={selected?.capacityBytes} step="1" bind:value={capacityBytes} disabled={running}/></label><p>{bytes(capacityBytes)} new volume</p>{/if}{#if running}<progress max="100" value={session.progress} aria-label="Disk operation progress"></progress>{/if}<p role="status">{session.message}</p><div class="disk-actions"><button onclick={() => send('disk.cancel')}>Cancel</button><button class="disk-default" disabled={!selected || running || !name.trim()} onclick={() => send(session.panel === 'erase' ? 'disk.erase' : 'disk.partition', session.panel === 'erase' ? { confirm: true, name, format } : { confirm: true, name, format, capacityBytes })}>{session.panel === 'erase' ? 'Erase Volume' : 'Apply Partition'}</button></div>
  {:else if session.panel === 'restore'}<h2>Restore “{selected?.name}”</h2><p>Replace erases all writable destination data, including Trash bytes, before restoring actual source bytes. Immutable OS/profile folders are retained. Keep Both and Skip are local merge alternatives, not a full-volume replacement.</p><label>Restore from<select data-disk-control="restore-source" bind:value={sourceRootId} disabled={running}><option value="">Choose a source volume</option>{#each volumes.filter(volume => volume.mounted && volume.id !== selected?.id) as volume}<option value={volume.rootFileId}>{volume.name}</option>{/each}</select></label><label>Restore mode<select bind:value={collision} disabled={running}><option value="replace">Erase writable destination data and restore</option><option value="keepBoth">Merge · keep both copies</option><option value="skip">Merge · skip existing files</option></select></label>{#if running}<progress max="100" value={session.progress} aria-label="Restore progress"></progress>{/if}<p role="status">{session.message}</p><div class="disk-actions"><button onclick={() => send('disk.cancel')}>Cancel</button><button class="disk-default" disabled={!sourceRootId || !selected || running} onclick={() => send('disk.restore', { confirm: true, sourceRootId, collision })}>Restore Volume</button></div>
  {:else if session.panel === 'image' || session.panel === 'convert'}<h2>{session.panel === 'convert' ? 'Convert Disk Image' : 'Disk Images'}</h2><label>{session.panel === 'convert' ? 'Image to convert' : 'Existing image'}<select data-disk-control="image-file" bind:value={imageFileId} disabled={running}><option value="">Choose an actual Files image</option>{#each imageFiles as file}<option value={file.id}>{file.name}</option>{/each}</select></label>{#if session.panel === 'image'}<button disabled={!imageFileId || running} onclick={() => send('disk.openImage', { fileId: imageFileId })}>Open Image</button><hr/><h3>Create New Image</h3>{/if}<label>Save As<input bind:value={name} disabled={running}/></label><label>Image format<select bind:value={imageFormat} disabled={running}><option value="iso">ISO9660 image (.iso)</option><option value="vhd">Fixed VHD · ISO9660 payload (.vhd)</option></select></label><p>Images are actual encoded Files documents, not renamed text or host disk images. Fixed VHD exports contain an ISO9660 filesystem, not a Windows FAT/NTFS disk. DMG and UDF images are not supported.</p>{#if running}<progress max="100" value={session.progress} aria-label="Image operation progress"></progress>{/if}<p role="status">{session.message}</p><div class="disk-actions"><button onclick={() => send('disk.cancel')}>Cancel</button><button class="disk-default" disabled={running || !name.trim() || (session.panel === 'convert' && !imageFileId)} onclick={() => send(session.panel === 'convert' ? 'disk.convertImage' : 'disk.createImage', session.panel === 'convert' ? { fileId: imageFileId, format: imageFormat, name } : { format: imageFormat, name })}>{session.panel === 'convert' ? 'Convert' : 'Create Image'}</button></div>
  {/if}
  {#if feedback}<p class="disk-error" role="alert">{feedback}</p>{/if}
 </section></div>
 {/if}
 <footer class="disk-status" role="status">{feedback || session.message || `${volumes.length} local volumes`}</footer>
</section>
{/if}
